import numpy as np


def sigmoid(x):
    return 1 / (1 + np.exp(-x))


def relu(x):
    return np.maximum(0, x)


def leaky_relu(x, alpha=0.01):
    return np.where(x > 0, x, alpha * x)


def softmax(x):
    e = np.exp(x - np.max(x))
    return e / e.sum()


def sigmoid_derivative(x):
    s = sigmoid(x)
    return s * (1 - s)


def show(label, value):
    print(label, None if value is None else np.round(value, 4))


x = np.array([-2.0, 0.0, 2.0])
show("sigmoid:", sigmoid(x))
show("relu:", relu(x))
show("leaky_relu:", leaky_relu(x))
show("softmax:", softmax(x))
show("sigmoid_derivative:", sigmoid_derivative(x))
